// Open invoices. In payrecon these come from PostgreSQL; here they are fixed test data.
const INVOICES = [
  { id: "INV-0001", customer: "Acme Hardware", amount: 1500 },
  { id: "INV-0006", customer: "Grace Wanjiku", amount: 50 },
  { id: "INV-0007", customer: "Peter Otieno", amount: 50 },
  { id: "INV-0008", customer: "Mary Achieng", amount: 50 },
];
// Code decides every exact match; the model is only asked about the rest.
const store = $getWorkflowStaticData("global");
store.paid = store.paid || {};
store.audit = store.audit || [];

const p = $input.first().json.body ?? $input.first().json;
const payment = {
  trans_id: String(p.trans_id ?? "").trim(),
  amount: Number(p.amount),
  payer_name: String(p.payer_name ?? "").trim(),
  bill_ref: String(p.bill_ref ?? "").trim().toUpperCase(),
};
if (!payment.trans_id || !Number.isFinite(payment.amount) || payment.amount <= 0) {
  return [{ json: { route: "invalid", payment, reason: "Missing transaction id or a positive amount." } }];
}
if (store.paid[payment.trans_id]) {
  return [{ json: { route: "duplicate", payment, reason: `Transaction ${payment.trans_id} was already applied to ${store.paid[payment.trans_id]}.` } }];
}
const exact = INVOICES.find((i) => i.id === payment.bill_ref && i.amount === payment.amount);
if (exact) {
  const alreadyPaid = Object.values(store.paid).includes(exact.id);
  if (alreadyPaid) {
    return [{ json: { route: "review", payment, candidates: [exact], reason: `Invoice ${exact.id} is already paid: possible double payment.` } }];
  }
  return [{ json: { route: "exact", payment, invoice: exact } }];
}
// Candidates: open invoices with the same amount. The model may only choose among these.
const candidates = INVOICES.filter((i) => i.amount === payment.amount && !Object.values(store.paid).includes(i.id));
return [{ json: { route: candidates.length ? "suggest" : "review", payment, candidates,
  reason: candidates.length ? "" : "No open invoice has this amount." } }];

// Apply an exact match and record it in the audit log.
const store = $getWorkflowStaticData("global");
const { payment, invoice } = $input.first().json;
store.paid[payment.trans_id] = invoice.id;
store.audit.push({ at: new Date().toISOString(), trans_id: payment.trans_id, invoice: invoice.id, by: "code (exact match)" });
return [{ json: { status: "paid", trans_id: payment.trans_id, invoice: invoice.id, decided_by: "code" } }];

// Build the request. The model gets the payment and the candidate invoices only.
const { payment, candidates } = $input.first().json;
const system = "You match one M-Pesa payment to one of the given candidate invoices. Payers often type nicknames or part of a name. Answer only with JSON: {\"invoice_id\": string or null, \"confidence\": \"high\"|\"medium\"|\"low\", \"reason\": one short plain-English sentence}. Use null when the evidence does not single out one invoice. Never invent an invoice id.";
const user = JSON.stringify({ payment, candidates });
return [{ json: { ...$input.first().json, request: {
  model: "claude-haiku-4-5-20251001", max_tokens: 300, system,
  messages: [{ role: "user", content: user }],
} } }];

// Guardrail: code checks the model's answer before a person sees it.
const prev = $("Build prompt").first().json;
const text = $input.first().json.content?.[0]?.text ?? "";
let s = { invoice_id: null, confidence: "low", reason: "The model's answer could not be read." };
try {
  const m = text.match(/\{[\s\S]*\}/);
  if (m) s = { ...s, ...JSON.parse(m[0]) };
} catch (e) {}
const ids = prev.candidates.map((c) => c.id);
if (s.invoice_id !== null && !ids.includes(s.invoice_id)) {
  s = { invoice_id: null, confidence: "low", reason: `The model named ${s.invoice_id}, which is not a candidate. Ignored.` };
}
if (!["high", "medium", "low"].includes(s.confidence)) s.confidence = "low";
return [{ json: { route: "review", payment: prev.payment, candidates: prev.candidates, suggestion: s,
  reason: s.reason } }];

// A person decided. Apply only an approved suggestion, and log every decision.
const store = $getWorkflowStaticData("global");
const item = $("Ask for approval").first().json;
const q = $input.first().json.query ?? {};
const decision = q.decision === "approve" ? "approve" : "reject";
const invoice = item.suggestion?.invoice_id ?? null;
if (decision === "approve" && invoice) store.paid[item.payment.trans_id] = invoice;
store.audit.push({ at: new Date().toISOString(), trans_id: item.payment.trans_id,
  invoice: decision === "approve" ? invoice : null, by: `person (${decision})`,
  suggested: invoice, reason: item.reason });
return [{ json: { status: decision === "approve" && invoice ? "paid" : "left open", trans_id: item.payment.trans_id, invoice: decision === "approve" ? invoice : null } }];

// Clears paid invoices and the audit log, so the evaluation starts from the same state.
const store = $getWorkflowStaticData("global");
store.paid = {};
store.audit = [];
return [{ json: { reset: true } }];
